import org.unicog.numberrace.ui.*;import javax.swing.*;import java.awt.*;import java.awt.image.BufferedImage;
public class V5Smoke {public static void main(String[] a)throws Exception{SwingUtilities.invokeAndWait(()->{BufferedImage im=new BufferedImage(800,600,2);Graphics2D g=im.createGraphics();new GameBackground().paint(g,800,600);if(GameAssets.load("background.jpg")==null)throw new AssertionError();for(int i=0;i<4;i++)if(PlayerAvatars.icon(i,42)==null)throw new AssertionError();JPanel p=new GamePanel();p.setSize(400,300);p.paint(g);JPanel h=new GameHeader();h.setSize(300,60);h.paint(g);JButton b=new JButton("Jogar!");b.setUI(new GameButton());b.setSize(200,60);b.setIcon(new GameIcon("play",20));b.paint(g);b.setEnabled(false);b.paint(g);JList<String> l=new JList<>(new String[]{"Ana"});PlayerCellRenderer r=new PlayerCellRenderer();Component c=r.getListCellRendererComponent(l,"Ana",0,true,true);c.setSize(300,60);c.paint(g);g.dispose();System.out.println("OK: assets and offscreen component painting");});}}
